(7220328, 1112634, 20364, '<td valign="top">looks like HDR a bit, nice vignetting on the edges and great colors that blend. 9</td>', 'looks like HDR a bit, nice vignetting on the edges and great colors that blend. 9', '2014-05-24 11:39:19.000000', NULL, 1),
(7220508, 1113049, 147314, '<td valign="top">Really good one - great colours, my favourite in this challenge.</td>', 'Really good one - great colours, my favourite in this challenge.', '2014-05-25 08:38:18.000000', NULL, 1),
(7220509, 1112886, 147314, '<td valign="top">Beautifully done, would love to know how you did this.</td>', 'Beautifully done, would love to know how you did this.', '2014-05-25 08:38:54.000000', NULL, 1),
(7220510, 1112902, 147314, '<td valign="top">Lovely, very fairytale-like.</td>', 'Lovely, very fairytale-like.', '2014-05-25 08:40:12.000000', NULL, 1),
(7220511, 1113051, 147314, '<td valign="top">Love this one, almost like a pencil drawing. Great processing!</td>', 'Love this one, almost like a pencil drawing. Great processing!', '2014-05-25 08:41:05.000000', NULL, 1),
(7220512, 1113036, 147314, '<td valign="top">Wow, beautiful. Like the almost Escher-like combination of all these creatures and the blue on black really works here. Great job!</td>', 'Wow, beautiful. Like the almost Escher-like combination of all these creatures and the blue on black really works here. Great job!', '2014-05-25 08:42:57.000000', NULL, 1),
(7220517, 1113036, 20799, '<td valign="top">Best wings in show.</td>', 'Best wings in show.', '2014-05-25 09:37:23.000000', NULL, 1),
(7220518, 1112950, 20799, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2014-05-25 09:37:47.000000', NULL, 1),
(7220519, 1112886, 20799, '<td valign="top">Very interesting effect, I wonder how this was done.</td>', 'Very interesting effect, I wonder how this was done.', '2014-05-25 09:38:54.000000', NULL, 1),
(7220524, 1112962, 173844, '<td valign="top">Godzilla has nothing on this guy.  Great idea, beautifully handled.  Great glossiness and detail.  Though we generally think of the raven as jet black, this image is actually a bouquet of blues.  I''d see this movie anytime.</td>', 'Godzilla has nothing on this guy.  Great idea, beautifully handled.  Great glossiness and detail.  Though we generally think of the raven as jet black, this image is actually a bouquet of blues.  I''d see this movie anytime.', '2014-05-25 11:14:51.000000', NULL, 1),
(7220527, 1113036, 173844, '<td valign="top">I love how these butterflies/moths have been transformed into an intricate and mysterious mask.  Like something out of Cirque du Soleil.  The nighttime coloration adds to the mood of fantasy and ritual.  Strong image.</td>', 'I love how these butterflies/moths have been transformed into an intricate and mysterious mask.  Like something out of Cirque du Soleil.  The nighttime coloration adds to the mood of fantasy and ritual.  Strong image.', '2014-05-25 11:21:30.000000', NULL, 1),
(7220531, 1112978, 63218, '<td valign="top">Razor-thin DOF makes this an interesting shot, with no context my imagination is free to make this as big or small as I want. I like it.</td>', 'Razor-thin DOF makes this an interesting shot, with no context my imagination is free to make this as big or small as I want. I like it.', '2014-05-25 12:38:00.000000', NULL, 1),
